import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const outputPath = join(root, "frontend/src/styles/tokens.css");
const checkOnly = process.argv.includes("--check");

const { staticVariables, semanticAliases } = await import(
  new URL("../frontend/src/design/tokens.ts", import.meta.url).href
);

const lines = [
  "/* Generated by scripts/generate-design-tokens.mjs. Do not edit by hand. */",
  ":root {",
  ...Object.entries(staticVariables).map(([key, value]) => `  --${key}: ${value};`),
  "",
  ...Object.entries(semanticAliases).map(([key, value]) => `  --${key}: ${value};`),
  "}",
  "",
].join("\n");

if (checkOnly) {
  const current = existsSync(outputPath) ? readFileSync(outputPath, "utf8") : "";
  if (current !== lines) {
    console.error("frontend/src/styles/tokens.css is out of date. Run: pnpm run design:tokens");
    process.exit(1);
  }
  console.log(`design tokens up to date (${Object.keys(staticVariables).length + Object.keys(semanticAliases).length} variables)`);
} else {
  mkdirSync(dirname(outputPath), { recursive: true });
  writeFileSync(outputPath, lines, "utf8");
  console.log(`wrote ${outputPath} (${Object.keys(staticVariables).length + Object.keys(semanticAliases).length} variables)`);
}
